<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { api, brl } from '@/services/api'
import { useSubscriptionsStore } from '@/stores/subscriptions'
import { currentMonth, formatDateBR, formatMonth, todayISO } from '@/utils/format'
import DateInput from '@/components/DateInput.vue'
import { useToast } from '@/composables/useToast'

const store = useSubscriptionsStore()
const toast = useToast()
const tab = ref('subscriptions')
const period = ref(currentMonth())
const detail = ref(null)
const paymentInvoice = ref(null)
const editingSubscriptionId = ref(null)
const contextMenu = ref(null)
const clientForm = reactive({ name: '', business_name: '', contact_name: '', whatsapp: '', email: '', notes: '', is_active: true })
const productForm = reactive({ name: '', description: '', is_active: true })
const planForm = reactive({ product_id: '', name: '', default_amount: '', billing_cycle: 'monthly', is_active: true })
const subscriptionForm = reactive({ client_id: '', product_id: '', plan_id: '', name: '', amount: '', billing_cycle: 'monthly', due_day: 1, start_date: todayISO(), end_date: '', notes: '' })
const paymentForm = reactive({ amount: '', paid_at: todayISO(), payment_method: 'pix', note: '' })

const cards = computed(() => [
  ['MRR contratado', store.dashboard?.mrr], ['Recebido no mês', store.dashboard?.received], ['Previsto no mês', store.dashboard?.expected], ['Em atraso', store.dashboard?.overdue], ['Assinaturas ativas', store.dashboard?.active_subscriptions],
])

async function load() { await store.load(period.value) }
function nullable(value) { return value?.trim?.() || null }
async function submitClient() {
  try { await api.createSaasClient({ ...clientForm, business_name: nullable(clientForm.business_name), contact_name: nullable(clientForm.contact_name), whatsapp: nullable(clientForm.whatsapp), email: nullable(clientForm.email), notes: nullable(clientForm.notes) }); Object.assign(clientForm, { name: '', business_name: '', contact_name: '', whatsapp: '', email: '', notes: '', is_active: true }); await load(); toast.success('Cliente cadastrado.') } catch (e) { store.error = e.message }
}
async function submitProduct() {
  try { await api.createSaasProduct({ ...productForm, description: nullable(productForm.description) }); Object.assign(productForm, { name: '', description: '', is_active: true }); await load(); toast.success('Produto cadastrado.') } catch (e) { store.error = e.message }
}
async function submitPlan() {
  try { await api.createSaasPlan({ ...planForm, product_id: Number(planForm.product_id), default_amount: Number(planForm.default_amount) }); Object.assign(planForm, { product_id: '', name: '', default_amount: '', billing_cycle: 'monthly', is_active: true }); await load(); toast.success('Plano cadastrado.') } catch (e) { store.error = e.message }
}
async function submitSubscription() {
  try {
    const payload = { ...subscriptionForm, client_id: Number(subscriptionForm.client_id), product_id: Number(subscriptionForm.product_id), plan_id: subscriptionForm.plan_id ? Number(subscriptionForm.plan_id) : null, amount: Number(subscriptionForm.amount), end_date: subscriptionForm.end_date || null, notes: nullable(subscriptionForm.notes) }
    const isEditing = Boolean(editingSubscriptionId.value)
    if (isEditing) await api.updateSaasSubscription(editingSubscriptionId.value, payload)
    else await api.createSaasSubscription(payload)
    resetSubscriptionForm()
    await load(); toast.success(isEditing ? 'Assinatura atualizada.' : 'Assinatura cadastrada.')
  } catch (e) { store.error = e.message }
}
function resetSubscriptionForm() { editingSubscriptionId.value = null; Object.assign(subscriptionForm, { client_id: '', product_id: '', plan_id: '', name: '', amount: '', billing_cycle: 'monthly', due_day: 1, start_date: todayISO(), end_date: '', notes: '' }) }
function openContextMenu(event, item) { contextMenu.value = { item, x: Math.min(event.clientX, window.innerWidth - 168), y: Math.min(event.clientY, window.innerHeight - 52) } }
function closeContextMenu() { contextMenu.value = null }
function editSubscription() {
  const item = contextMenu.value?.item
  if (!item || ['canceled', 'ended'].includes(item.status)) return
  editingSubscriptionId.value = item.id
  Object.assign(subscriptionForm, { client_id: String(item.client_id), product_id: String(item.product_id), plan_id: item.plan_id ? String(item.plan_id) : '', name: item.name, amount: item.amount, billing_cycle: item.billing_cycle, due_day: item.due_day, start_date: item.start_date, end_date: item.end_date || '', notes: item.notes || '' })
  closeContextMenu()
  window.scrollTo({ top: 0, behavior: 'smooth' })
}
async function openDetail(item) { try { detail.value = await api.saasSubscription(item.id) } catch (e) { store.error = e.message } }
async function changeStatus(item, action) {
  try {
    if (action === 'cancel' && !window.confirm(`Cancelar “${item.name}”? O histórico será preservado.`)) return
    await (action === 'pause' ? api.pauseSaasSubscription(item.id) : action === 'resume' ? api.resumeSaasSubscription(item.id) : api.cancelSaasSubscription(item.id, { canceled_at: todayISO() }))
    await load(); if (detail.value?.id === item.id) await openDetail(item); toast.success(action === 'cancel' ? 'Assinatura cancelada.' : action === 'pause' ? 'Assinatura pausada.' : 'Assinatura reativada.')
  } catch (e) { store.error = e.message }
}
async function generateYear() { try { await api.generateSaasInvoices({}); await load(); toast.success('Cobranças geradas até os próximos 12 meses.') } catch (e) { store.error = e.message } }
function openPayment(invoice) { paymentInvoice.value = invoice; Object.assign(paymentForm, { amount: invoice.remaining_amount, paid_at: todayISO(), payment_method: 'pix', note: '' }) }
async function submitPayment() {
  try { await api.addSaasPayment(paymentInvoice.value.id, { ...paymentForm, amount: Number(paymentForm.amount), note: nullable(paymentForm.note) }); paymentInvoice.value = null; await load(); if (detail.value) await openDetail(detail.value); toast.success('Recebimento registrado como receita.') } catch (e) { store.error = e.message }
}
async function undoPayment(payment) {
  if (!window.confirm('Estornar este recebimento? A receita financeira vinculada também será removida.')) return
  try { await api.deleteSaasPayment(payment.id); await load(); if (detail.value) await openDetail(detail.value); toast.success('Recebimento estornado.') } catch (e) { store.error = e.message }
}
onMounted(() => { load(); window.addEventListener('click', closeContextMenu); window.addEventListener('scroll', closeContextMenu, true) })
onBeforeUnmount(() => { window.removeEventListener('click', closeContextMenu); window.removeEventListener('scroll', closeContextMenu, true) })
</script>

<template>
  <div>
    <header class="page-header"><div><h1>Assinaturas SaaS</h1><p>Contratos da Tervo, cobranças e receita recebida.</p></div><label class="period">Período<input v-model="period" type="month" class="input" @change="load" /></label></header>
    <p v-if="store.error" class="message" role="alert">{{ store.error }}</p>
    <section class="metric-grid"><article v-for="([label, value]) in cards" :key="label" class="card metric"><span>{{ label }}</span><strong>{{ label === 'Assinaturas ativas' ? value || 0 : brl(value) }}</strong></article></section>
    <nav class="tabs" aria-label="Seções de assinaturas"><button v-for="item in [['subscriptions','Assinaturas'],['invoices','Cobranças'],['clients','Clientes'],['catalog','Produtos e planos']]" :key="item[0]" :class="{ active: tab === item[0] }" @click="tab = item[0]">{{ item[1] }}</button></nav>

    <section v-if="tab === 'subscriptions'" class="workspace">
      <form class="card form-grid" @submit.prevent="submitSubscription"><h2 class="full">{{ editingSubscriptionId ? 'Editar assinatura' : 'Nova assinatura' }}</h2><label>Cliente<select v-model="subscriptionForm.client_id" class="input" required><option disabled value="">Selecione</option><option v-for="item in store.clients.filter(x => x.is_active)" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Produto<select v-model="subscriptionForm.product_id" class="input" required><option disabled value="">Selecione</option><option v-for="item in store.products.filter(x => x.is_active)" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Plano (opcional)<select v-model="subscriptionForm.plan_id" class="input"><option value="">Personalizado</option><option v-for="item in store.plans.filter(x => x.product_id === Number(subscriptionForm.product_id) && x.is_active)" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Nome do contrato<input v-model="subscriptionForm.name" class="input" required maxlength="150" placeholder="Ex.: Gestão mensal" /></label><label>Valor<input v-model="subscriptionForm.amount" class="input" required type="number" min="0.01" step="0.01" /></label><label>Ciclo<select v-model="subscriptionForm.billing_cycle" class="input"><option value="monthly">Mensal</option><option value="quarterly">Trimestral</option><option value="semiannual">Semestral</option><option value="yearly">Anual</option></select></label><label>Dia de vencimento<input v-model.number="subscriptionForm.due_day" class="input" required type="number" min="1" max="28" /></label><label>Início<DateInput v-model="subscriptionForm.start_date" required /></label><label>Término (opcional)<DateInput v-model="subscriptionForm.end_date" /></label><label class="full">Observações<textarea v-model="subscriptionForm.notes" class="input" maxlength="500" /></label><div class="full"><button class="button">{{ editingSubscriptionId ? 'Salvar alterações' : 'Cadastrar assinatura' }}</button><button v-if="editingSubscriptionId" type="button" class="button button--ghost" @click="resetSubscriptionForm">Cancelar</button><button v-else type="button" class="button button--ghost" @click="generateYear">Gerar 12 meses</button></div></form>
      <div class="card table-card"><div class="section-heading"><h2>Contratos</h2><span>{{ store.subscriptions.length }} registros</span></div><p v-if="store.loading" class="empty">Carregando…</p><table v-else><thead><tr><th>Cliente</th><th>Produto</th><th>Valor</th><th>Próximo vencimento</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="item in store.subscriptions" :key="item.id" @contextmenu.prevent="openContextMenu($event, item)"><td>{{ item.client_name }}<small>{{ item.name }}</small></td><td>{{ item.product_name }}</td><td>{{ brl(item.amount) }}</td><td>{{ formatDateBR(item.next_due_date) || '—' }}</td><td><span :class="['status', item.status]">{{ item.status }}</span></td><td class="actions"><button class="link" @click="openDetail(item)">Ver</button><button v-if="item.status === 'active'" class="link" @click="changeStatus(item, 'pause')">Pausar</button><button v-if="item.status === 'paused'" class="link" @click="changeStatus(item, 'resume')">Retomar</button><button v-if="!['canceled','ended'].includes(item.status)" class="link danger" @click="changeStatus(item, 'cancel')">Cancelar</button></td></tr></tbody></table></div>
    </section>

    <section v-if="tab === 'invoices'" class="card table-card"><div class="section-heading"><div><h2>Cobranças de {{ formatMonth(period) }}</h2><p>O previsto não altera o saldo até a confirmação do recebimento.</p></div></div><table><thead><tr><th>Vencimento</th><th>Cliente</th><th>Produto</th><th>Cobrado</th><th>Pendente</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="item in store.invoices" :key="item.id"><td>{{ formatDateBR(item.due_date) }}</td><td>{{ item.client_name }}</td><td>{{ item.product_name }}</td><td>{{ brl(item.amount) }}</td><td>{{ brl(item.remaining_amount) }}</td><td><span :class="['status', item.status]">{{ item.status }}</span></td><td><button v-if="item.remaining_amount" class="link" @click="openPayment(item)">Registrar pagamento</button></td></tr></tbody></table><p v-if="!store.invoices.length" class="empty">Nenhuma cobrança neste período.</p></section>

    <section v-if="tab === 'clients'" class="two-columns"><form class="card form-grid" @submit.prevent="submitClient"><h2 class="full">Novo cliente</h2><label>Nome<input v-model="clientForm.name" class="input" required /></label><label>Razão social<input v-model="clientForm.business_name" class="input" /></label><label>Contato<input v-model="clientForm.contact_name" class="input" /></label><label>WhatsApp<input v-model="clientForm.whatsapp" class="input" /></label><label>Email<input v-model="clientForm.email" class="input" type="email" /></label><label class="full">Observações<textarea v-model="clientForm.notes" class="input" /></label><div class="full"><button class="button">Cadastrar cliente</button></div></form><section class="card list"><h2>Clientes</h2><div v-for="item in store.clients" :key="item.id"><b>{{ item.name }}</b><span>{{ item.business_name || item.contact_name || 'Sem contato informado' }}</span><em v-if="!item.is_active">Arquivado</em></div><p v-if="!store.clients.length" class="empty">Nenhum cliente cadastrado.</p></section></section>

    <section v-if="tab === 'catalog'" class="two-columns"><div><form class="card form-grid" @submit.prevent="submitProduct"><h2 class="full">Novo produto</h2><label>Nome<input v-model="productForm.name" class="input" required /></label><label>Descrição<input v-model="productForm.description" class="input" /></label><div class="full"><button class="button">Cadastrar produto</button></div></form><section class="card list"><h2>Produtos</h2><div v-for="item in store.products" :key="item.id"><b>{{ item.name }}</b><span>{{ item.description || 'Sem descrição' }}</span></div></section></div><div><form class="card form-grid" @submit.prevent="submitPlan"><h2 class="full">Novo plano</h2><label>Produto<select v-model="planForm.product_id" class="input" required><option disabled value="">Selecione</option><option v-for="item in store.products.filter(x => x.is_active)" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Nome<input v-model="planForm.name" class="input" required /></label><label>Valor padrão<input v-model="planForm.default_amount" class="input" required type="number" min="0.01" step="0.01" /></label><label>Ciclo<select v-model="planForm.billing_cycle" class="input"><option value="monthly">Mensal</option><option value="quarterly">Trimestral</option><option value="semiannual">Semestral</option><option value="yearly">Anual</option></select></label><div class="full"><button class="button">Cadastrar plano</button></div></form><section class="card list"><h2>Planos</h2><div v-for="item in store.plans" :key="item.id"><b>{{ item.name }}</b><span>{{ item.product_name }} · {{ brl(item.default_amount) }} / {{ item.billing_cycle }}</span></div></section></div></section>

    <aside v-if="detail" class="drawer"><header><div><span>Detalhe do contrato</span><h2>{{ detail.name }}</h2><p>{{ detail.client_name }} · {{ detail.product_name }}</p></div><button class="link" @click="detail = null">Fechar</button></header><p><span :class="['status', detail.status]">{{ detail.status }}</span> {{ brl(detail.amount) }} · vencimento dia {{ detail.due_day }}</p><h3>Histórico de cobranças</h3><div v-for="invoice in detail.invoices" :key="invoice.id" class="invoice-row"><div><b>{{ formatMonth(invoice.reference_period) }}</b><small>{{ formatDateBR(invoice.due_date) }} · {{ invoice.status }}</small></div><strong>{{ brl(invoice.paid_amount) }} de {{ brl(invoice.amount) }}</strong><button v-if="invoice.remaining_amount" class="link" @click="openPayment(invoice)">Receber</button><button v-for="pay in invoice.payments" :key="pay.id" class="link danger" @click="undoPayment(pay)">Estornar {{ brl(pay.amount) }}</button></div></aside>
    <div v-if="contextMenu" class="context-menu" :style="{ left: `${contextMenu.x}px`, top: `${contextMenu.y}px` }" role="menu" @click.stop><button type="button" role="menuitem" :disabled="['canceled', 'ended'].includes(contextMenu.item.status)" @click="editSubscription">Editar</button></div>
    <div v-if="paymentInvoice" class="modal-backdrop"><form class="card payment-modal" @submit.prevent="submitPayment"><h2>Registrar pagamento</h2><p>{{ paymentInvoice.client_name }} · {{ brl(paymentInvoice.remaining_amount) }} pendente</p><label>Valor<input v-model="paymentForm.amount" class="input" type="number" min="0.01" :max="paymentInvoice.remaining_amount" step="0.01" required /></label><label>Data<DateInput v-model="paymentForm.paid_at" :max="todayISO()" required /></label><label>Forma de pagamento<select v-model="paymentForm.payment_method" class="input"><option value="pix">Pix</option><option value="transfer">Transferência</option><option value="cash">Dinheiro</option><option value="card">Cartão</option><option value="other">Outro</option></select></label><label>Observação<input v-model="paymentForm.note" class="input" /></label><footer><button type="button" class="button button--ghost" @click="paymentInvoice = null">Cancelar</button><button class="button">Confirmar recebimento</button></footer></form></div>
  </div>
</template>

<style scoped>
.period { display: grid; gap: 5px; color: var(--color-text-secondary); font-size: 12px; }.metric-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 12px; margin-bottom: 20px; }.metric { padding: 15px; }.metric span { color: var(--color-text-secondary); font-size: 11px; }.metric strong { display: block; margin-top: 8px; font-size: 18px; }.tabs { display: flex; gap: 5px; margin-bottom: 16px; border-bottom: 1px solid var(--color-border); }.tabs button, .link { border: 0; background: none; color: var(--color-text-secondary); cursor: pointer; }.tabs button { padding: 10px 13px; }.tabs button.active { color: var(--color-text-primary); border-bottom: 2px solid var(--color-accent); }.workspace { display: grid; gap: 16px; }.form-grid h2, .list h2, .table-card h2 { margin: 0; font-size: 16px; }.form-grid textarea { min-height: 70px; resize: vertical; }.button--ghost { margin-left: 8px; }.table-card { overflow-x: auto; }.section-heading { display: flex; justify-content: space-between; margin-bottom: 14px; }.section-heading p { margin: 5px 0 0; color: var(--color-text-secondary); font-size: 12px; } table { width: 100%; border-collapse: collapse; font-size: 13px; } th { color: var(--color-text-muted); font-size: 11px; font-weight: 500; text-align: left; } th, td { padding: 12px 8px; border-bottom: 1px solid var(--color-border); } td small { display: block; color: var(--color-text-muted); margin-top: 3px; }.actions { white-space: nowrap; }.danger { color: var(--color-danger); }.status { display: inline-block; padding: 3px 6px; border-radius: 4px; color: var(--color-text-secondary); background: var(--color-surface-raised); font-size: 10px; text-transform: capitalize; }.status.active, .status.paid { color: var(--color-success); background: var(--color-success-bg); }.status.overdue, .status.canceled { color: var(--color-danger); background: var(--color-danger-bg); }.status.partial { color: #e7b84b; background: rgba(231,184,75,.12); }.two-columns { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }.two-columns > div { display: grid; align-content: start; gap: 16px; }.list { margin-top: 16px; }.list > div { display: grid; gap: 3px; padding: 12px 0; border-bottom: 1px solid var(--color-border); }.list span { color: var(--color-text-secondary); font-size: 12px; }.list em { color: var(--color-danger); font-size: 11px; }.drawer { position: fixed; z-index: 20; top: 0; right: 0; width: min(520px, 48vw); height: 100vh; padding: 24px; overflow: auto; background: var(--color-surface-raised); border-left: 1px solid var(--color-border-strong); box-shadow: -12px 0 35px rgba(0,0,0,.3); }.drawer header { display: flex; justify-content: space-between; }.drawer header span, .drawer p, .invoice-row small { color: var(--color-text-secondary); font-size: 12px; }.drawer h2 { margin: 6px 0; }.drawer h3 { margin-top: 26px; font-size: 14px; }.invoice-row { display: grid; grid-template-columns: 1fr auto; gap: 8px; align-items: center; padding: 12px 0; border-bottom: 1px solid var(--color-border); }.invoice-row b, .invoice-row small { display: block; }.invoice-row .link { grid-column: 2; }.modal-backdrop { position: fixed; z-index: 30; inset: 0; display: grid; place-items: center; background: rgba(0,0,0,.55); }.payment-modal { width: 440px; display: grid; gap: 13px; }.payment-modal h2, .payment-modal p { margin: 0; }.payment-modal p { color: var(--color-text-secondary); font-size: 13px; }.payment-modal label { display: grid; gap: 6px; color: var(--color-text-secondary); font-size: 12px; }.payment-modal footer { display: flex; justify-content: end; }.context-menu { position: fixed; z-index: 40; display: grid; width: 160px; padding: 4px; border: 1px solid var(--color-border-strong); border-radius: 7px; background: var(--color-surface-raised); box-shadow: 0 10px 30px rgba(0, 0, 0, .28); }.context-menu button { border: 0; border-radius: 4px; padding: 8px 10px; color: var(--color-text-primary); text-align: left; background: transparent; cursor: pointer; font-size: 13px; }.context-menu button:hover { background: var(--color-surface); }.context-menu button:disabled { color: var(--color-text-muted); cursor: not-allowed; }.empty { color: var(--color-text-secondary); text-align: center; padding: 20px; } @media (max-width: 1180px) { .metric-grid { grid-template-columns: repeat(3, 1fr); } }
</style>
